     position: relative;
     display: inline-block; // or block, depending on your layout
   }

   .input-container input {
     padding-right: 30px; // enough space for the icon
     // other styles for the input
   }

   .search-icon-button {
     position: absolute;
     right: 5px; // adjust as needed
     top: 50%;
     transform: translateY(-50%);
     background: none;
     border: none;
     cursor: pointer;
     // You might want to adjust padding, etc.
   }

   // Also, make sure the button doesn't interfere with the input's focus, etc.

